# Test lookup_user function
def test_lookup_user():
    # Mock database connection and cursor
    mock_db_conn = MagicMock()
    mock_cursor = mock_db_conn.cursor.return_value.__enter__.return_value
    mock_cursor.fetchall.return_value = [{"id": 1, "username": "testuser"}]

    # Test normal behavior
    result = lookup_user(mock_db_conn, "testuser")
    mock_cursor.execute.assert_called_once_with("SELECT * FROM users WHERE username = %s", ("testuser",))
    assert result == [{"id": 1, "username": "testuser"}]

    # Test with empty username
    result = lookup_user(mock_db_conn, "")
    mock_cursor.execute.assert_called_with("SELECT * FROM users WHERE username = %s", ("",))
    assert result == []

